1	const NODE_TYPES = new Set(['trigger', 'form', 'condition', 'action', 'end']);
2	const FIELD_TYPES = new Set(['string', 'number', 'integer', 'boolean']);
3	const FORBIDDEN_SEGMENTS = new Set(['__proto__', 'prototype', 'constructor']);
4	const STRING_BOUNDS = new Set(['minLength', 'maxLength']);
5	const NUMBER_BOUNDS = new Set(['min', 'max']);
6	
7	function assertPlainObject(value, label) {
8	  if (!value || typeof value !== 'object' || Array.isArray(value)) {
9	    throw new TypeError(`${label} must be an object`);
10	  }
11	}
12	
13	function isUsableObject(value) {
14	  return value !== null && typeof value === 'object' && !Array.isArray(value);
15	}
16	
17	function valueMatchesType(value, type) {
18	  if (type === 'string') return typeof value === 'string';
19	  if (type === 'boolean') return typeof value === 'boolean';
20	  if (typeof value !== 'number') return false;
21	  if (type === 'number') return Number.isFinite(value);
22	  return Number.isInteger(value);
23	}
24	
25	function valueSatisfiesBounds(value, spec) {
26	  if (spec.type === 'string') {
27	    const length = [...value].length;
28	    if (spec.minLength !== undefined && length < spec.minLength) return false;
29	    if (spec.maxLength !== undefined && length > spec.maxLength) return false;
30	  } else if (spec.type === 'number' || spec.type === 'integer') {
31	    if (spec.min !== undefined && value < spec.min) return false;
32	    if (spec.max !== undefined && value > spec.max) return false;
33	  }
34	  return true;
35	}
36	
37	function compileFormSchema(node) {
38	  if (!Object.hasOwn(node, 'schema') || node.schema === undefined) return null;
39	  if (!isUsableObject(node.schema)) {
40	    throw new Error(`form node ${node.id}: schema must be an object`);
41	  }
42	  if (!Array.isArray(node.schema.fields)) {
43	    throw new Error(`form node ${node.id}: schema.fields must be an array`);
44	  }
45	
46	  const seenSegments = [];
47	  const compiled = [];
48	  node.schema.fields.forEach((field, index) => {
49	    const label = `form node ${node.id} field ${field && isUsableObject(field) && typeof field.path === 'string' && field.path ? field.path : `#${index}`}`;
50	    if (!isUsableObject(field)) {
51	      throw new Error(`${label}: field must be an object`);
52	    }
53	    if (typeof field.path !== 'string' || field.path.length === 0) {
54	      throw new Error(`form node ${node.id} field #${index}: path must be a non-empty string`);
55	    }
56	    const segments = field.path.split('.');
57	    if (segments.some(part => part.length === 0)) {
58	      throw new Error(`${label}: path must not contain empty segments`);
59	    }
60	    if (segments.some(part => FORBIDDEN_SEGMENTS.has(part))) {
61	      throw new Error(`${label}: path must not contain __proto__, prototype or constructor segments`);
62	    }
63	    for (const previous of seenSegments) {
64	      const shared = Math.min(previous.length, segments.length);
65	      let prefix = true;
66	      for (let i = 0; i < shared; i += 1) {
67	        if (previous[i] !== segments[i]) { prefix = false; break; }
68	      }
69	      if (prefix && previous.length === segments.length) {
70	        throw new Error(`${label}: duplicate field path`);
71	      }
72	      if (prefix) {
73	        throw new Error(`${label}: field paths must not be parent and child of each other`);
74	      }
75	    }
76	    seenSegments.push(segments);
77	
78	    if (!FIELD_TYPES.has(field.type)) {
79	      throw new Error(`${label}: unknown field type ${field.type}`);
80	    }
81	    const spec = { path: field.path, segments, type: field.type, required: false, hasDefault: false };
82	
83	    if (Object.hasOwn(field, 'required')) {
84	      if (typeof field.required !== 'boolean') {
85	        throw new Error(`${label}: required must be a boolean`);
86	      }
87	      spec.required = field.required;
88	    }
89	
90	    const applicableBounds = field.type === 'string' ? STRING_BOUNDS
91	      : (field.type === 'number' || field.type === 'integer') ? NUMBER_BOUNDS
92	      : new Set();
93	    for (const bound of ['minLength', 'maxLength', 'min', 'max']) {
94	      if (!Object.hasOwn(field, bound) || field[bound] === undefined) continue;
95	      if (!applicableBounds.has(bound)) {
96	        throw new Error(`${label}: ${bound} does not apply to ${field.type} fields`);
97	      }
98	      const value = field[bound];
99	      if (field.type === 'string') {
100	        if (typeof value !== 'number' || !Number.isInteger(value) || value < 0) {
101	          throw new Error(`${label}: ${bound} must be a non-negative integer`);
102	        }
103	      } else if (typeof value !== 'number' || !Number.isFinite(value)) {
104	        throw new Error(`${label}: ${bound} must be a finite number`);
105	      }
106	      spec[bound] = value;
107	    }
108	    if (spec.minLength !== undefined && spec.maxLength !== undefined && spec.minLength > spec.maxLength) {
109	      throw new Error(`${label}: minLength must not be greater than maxLength`);
110	    }
111	    if (spec.min !== undefined && spec.max !== undefined && spec.min > spec.max) {
112	      throw new Error(`${label}: min must not be greater than max`);
113	    }
114	
115	    if (Object.hasOwn(field, 'default') && field.default !== undefined) {
116	      const fallback = field.default;
117	      if (!valueMatchesType(fallback, spec.type)) {
118	        throw new Error(`${label}: default value does not match field type ${spec.type}`);
119	      }
120	      if (!valueSatisfiesBounds(fallback, spec)) {
121	        throw new Error(`${label}: default value violates field constraints`);
122	      }
123	      spec.hasDefault = true;
124	      spec.default = fallback;
125	    }
126	
127	    compiled.push(spec);
128	  });
129	
130	  return compiled;
131	}
132	
133	const MAX_CONDITION_DEPTH = 32;
134	
135	function parsePathSegments(path, label) {
136	  if (typeof path !== 'string' || path.length === 0) {
137	    throw new Error(`${label}: path must be a non-empty string`);
138	  }
139	  const segments = path.split('.');
140	  if (segments.some(part => part.length === 0)) {
141	    throw new Error(`${label}: path must not contain empty segments`);
142	  }
143	  if (segments.some(part => FORBIDDEN_SEGMENTS.has(part))) {
144	    throw new Error(`${label}: path must not contain __proto__, prototype or constructor segments`);
145	  }
146	  return segments;
147	}
148	
149	function isComparableConstant(value) {
150	  return value === null || typeof value === 'string' || typeof value === 'boolean'
151	    || (typeof value === 'number' && Number.isFinite(value));
152	}
153	
154	function toComparableNumber(value) {
155	  // Objects and arrays never participate in numeric comparison, even though
156	  // Number([]) === 0; everything else uses JS numeric conversion.
157	  if (value !== null && typeof value === 'object') return null;
158	  const converted = Number(value);
159	  return Number.isFinite(converted) ? converted : null;
160	}
161	
162	// Walks every condition node (including untaken branches) and turns it into a
163	// pre-validated, pre-resolved structure. Any malformed condition throws with a
164	// node id and a `$`-style child position, before the workflow can execute.
165	function compileCondition(condition, nodeId, position = '$', depth = 1) {
166	  if (depth > MAX_CONDITION_DEPTH) {
167	    throw new Error(`condition node ${nodeId} at ${position}: conditions must not be nested deeper than ${MAX_CONDITION_DEPTH} levels`);
168	  }
169	  if (!isUsableObject(condition)) {
170	    throw new Error(`condition node ${nodeId} at ${position}: condition must be an object`);
171	  }
172	
173	  const comboKeys = [];
174	  if (Object.hasOwn(condition, 'all')) comboKeys.push('all');
175	  if (Object.hasOwn(condition, 'any')) comboKeys.push('any');
176	  if (Object.hasOwn(condition, 'not')) comboKeys.push('not');
177	  if (comboKeys.length > 1) {
178	    throw new Error(`condition node ${nodeId} at ${position}: condition must use only one of all, any or not`);
179	  }
180	
181	  const comparisonKeys = ['field', 'operator', 'value', 'valueField'];
182	  const presentComparisonKeys = comparisonKeys.filter(key => Object.hasOwn(condition, key));
183	
184	  if (comboKeys.length === 1) {
185	    if (presentComparisonKeys.length > 0) {
186	      throw new Error(`condition node ${nodeId} at ${position}: ${comboKeys[0]} condition must not mix in field, operator, value or valueField`);
187	    }
188	    const key = comboKeys[0];
189	    if (key === 'not') {
190	      return { kind: 'not', child: compileCondition(condition.not, nodeId, `${position}.not`, depth + 1) };
191	    }
192	    if (!Array.isArray(condition[key])) {
193	      throw new Error(`condition node ${nodeId} at ${position}: ${key} must be an array of conditions`);
194	    }
195	    if (condition[key].length === 0) {
196	      throw new Error(`condition node ${nodeId} at ${position}: ${key} must not be empty`);
197	    }
198	    return {
199	      kind: key,
200	      children: condition[key].map((child, index) =>
201	        compileCondition(child, nodeId, `${position}.${key}[${index}]`, depth + 1)),
202	    };
203	  }
204	
205	  const where = `condition node ${nodeId} at ${position}`;
206	  if (!Object.hasOwn(condition, 'field') || !Object.hasOwn(condition, 'operator')) {
207	    throw new Error(`${where}: condition must be a comparison (field and operator) or a compound (all, any or not)`);
208	  }
209	  const segments = parsePathSegments(condition.field, `${where} field`);
210	
211	  if (!['eq', 'gte', 'lte', 'exists'].includes(condition.operator)) {
212	    throw new Error(`${where}: unknown condition operator: ${condition.operator}`);
213	  }
214	
215	  const unexpected = presentComparisonKeys.filter(key => key !== 'field' && key !== 'operator');
216	  if (condition.operator === 'exists') {
217	    if (unexpected.length > 0) {
218	      throw new Error(`${where}: exists only takes field and operator`);
219	    }
220	    return { kind: 'comparison', operator: 'exists', segments };
221	  }
222	
223	  const hasValue = Object.hasOwn(condition, 'value');
224	  const hasValueField = Object.hasOwn(condition, 'valueField');
225	  if (hasValue === hasValueField) {
226	    throw new Error(`${where}: condition must specify exactly one of value or valueField`);
227	  }
228	  if (hasValueField) {
229	    if (typeof condition.valueField !== 'string') {
230	      throw new Error(`${where} valueField: path must be a non-empty string`);
231	    }
232	    return {
233	      kind: 'comparison', operator: condition.operator, segments,
234	      valueSegments: parsePathSegments(condition.valueField, `${where} valueField`),
235	    };
236	  }
237	  if (!isComparableConstant(condition.value)) {
238	    throw new Error(`${where}: value must be a string, finite number, boolean or null`);
239	  }
240	  const compiled = { kind: 'comparison', operator: condition.operator, segments, value: condition.value };
241	  if (condition.operator !== 'eq') {
242	    compiled.numericValue = toComparableNumber(condition.value);
243	    if (compiled.numericValue === null) {
244	      throw new Error(`${where}: value for ${condition.operator} must convert to a finite number`);
245	    }
246	  }
247	  return compiled;
248	}
249	
250	const formSchemas = new WeakMap();
251	const compiledConditions = new WeakMap();
252	const successorTargets = new WeakMap();
253	const nodeDependencies = new WeakMap();
254	const actionBindings = new WeakMap();
255	
256	const RETRY_FIELDS = ['attempts', 'initialDelayMs', 'backoffFactor', 'maxDelayMs'];
257	
258	function isIntegerIn(value, min, max) {
259	  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
260	}
261	
262	// An action node either keeps the legacy `message` behavior or names a
263	// business operation the caller supplies at run time. The retry block is
264	// either absent (one attempt, no waiting) or present with all four
265	// parameters together.
266	function compileAction(node) {
267	  let name = null;
268	  if (Object.hasOwn(node, 'operation') && node.operation !== undefined) {
269	    if (typeof node.operation !== 'string' || node.operation.trim().length === 0) {
270	      throw new Error(`action node ${node.id}: operation must be a non-empty string name`);
271	    }
272	    name = node.operation;
273	  }
274	
275	  const retry = { attempts: 1, initialDelayMs: 0, backoffFactor: 1, maxDelayMs: 0 };
276	  if (Object.hasOwn(node, 'retry') && node.retry !== undefined) {
277	    if (!name) {
278	      throw new Error(`action node ${node.id}: retry config is only allowed on an action that names an operation`);
279	    }
280	    const config = node.retry;
281	    if (!isUsableObject(config)) {
282	      throw new Error(`action node ${node.id}: retry must be an object`);
283	    }
284	    const missing = RETRY_FIELDS.filter(field => !Object.hasOwn(config, field) || config[field] === undefined);
285	    if (missing.length > 0) {
286	      throw new Error(`action node ${node.id}: retry config must define all of ${RETRY_FIELDS.join(', ')} together (missing: ${missing.join(', ')})`);
287	    }
288	    if (!isIntegerIn(config.attempts, 1, 10)) {
289	      throw new Error(`action node ${node.id}: retry.attempts must be an integer between 1 and 10`);
290	    }
291	    if (!isIntegerIn(config.initialDelayMs, 0, 60000)) {
292	      throw new Error(`action node ${node.id}: retry.initialDelayMs must be an integer between 0 and 60000 milliseconds`);
293	    }
294	    if (!isIntegerIn(config.maxDelayMs, 0, 60000)) {
295	      throw new Error(`action node ${node.id}: retry.maxDelayMs must be an integer between 0 and 60000 milliseconds`);
296	    }
297	    if (typeof config.backoffFactor !== 'number' || !Number.isFinite(config.backoffFactor)
298	      || config.backoffFactor < 1 || config.backoffFactor > 4) {
299	      throw new Error(`action node ${node.id}: retry.backoffFactor must be a finite number between 1 and 4`);
300	    }
301	    if (config.maxDelayMs < config.initialDelayMs) {
302	      throw new Error(`action node ${node.id}: retry.maxDelayMs must not be less than retry.initialDelayMs`);
303	    }
304	    retry.attempts = config.attempts;
305	    retry.initialDelayMs = config.initialDelayMs;
306	    retry.backoffFactor = config.backoffFactor;
307	    retry.maxDelayMs = config.maxDelayMs;
308	  }
309	
310	  return { name, retry };
311	}
312	
313	// Resolves the outgoing edges of a node. Trigger, form and action nodes may
314	// name a single successor or a non-empty, duplicate-free array of successors;
315	// conditions keep their then/else pair and end nodes have none.
316	function normalizeSuccessors(node, nodes) {
317	  if (node.type === 'end') return [];
318	  if (node.type === 'condition') {
319	    for (const destination of [node.then, node.else]) {
320	      if (typeof destination !== 'string' || !nodes.has(destination)) {
321	        throw new Error(`node ${node.id} points to an unknown destination`);
322	      }
323	    }
324	    return [node.then, node.else];
325	  }
326	  const next = node.next;
327	  if (Array.isArray(next)) {
328	    if (next.length === 0) {
329	      throw new Error(`node ${node.id}: next array must not be empty`);
330	    }
331	    const seen = new Set();
332	    for (const destination of next) {
333	      if (typeof destination !== 'string') {
334	        throw new Error(`node ${node.id}: next array entries must be node id strings`);
335	      }
336	      if (seen.has(destination)) {
337	        throw new Error(`node ${node.id}: duplicate destination ${destination}`);
338	      }
339	      seen.add(destination);
340	      if (!nodes.has(destination)) {
341	        throw new Error(`node ${node.id} points to an unknown destination`);
342	      }
343	    }
344	    return [...seen];
345	  }
346	  if (typeof next !== 'string' || !nodes.has(next)) {
347	    throw new Error(`node ${node.id} points to an unknown destination`);
348	  }
349	  return [next];
350	}
351	
352	// Resolves the explicit dependencies of a node. Dependencies only gate when a
353	// node may run; they never activate it. A missing dependsOn means no
354	// dependencies, and the entry node must not declare any.
355	function normalizeDependencies(node, nodes, entryId) {
356	  if (!Object.hasOwn(node, 'dependsOn') || node.dependsOn === undefined) return [];
357	  if (!Array.isArray(node.dependsOn)) {
358	    throw new Error(`node ${node.id}: dependsOn must be an array`);
359	  }
360	  const seen = new Set();
361	  for (const dependency of node.dependsOn) {
362	    if (typeof dependency !== 'string') {
363	      throw new Error(`node ${node.id}: dependsOn entries must be node id strings`);
364	    }
365	    if (seen.has(dependency)) {
366	      throw new Error(`node ${node.id}: duplicate dependency ${dependency}`);
367	    }
368	    seen.add(dependency);
369	    if (!nodes.has(dependency)) {
370	      throw new Error(`node ${node.id} depends on an unknown node`);
371	    }
372	    if (dependency === node.id) {
373	      throw new Error(`node ${node.id} must not depend on itself`);
374	    }
375	  }
376	  const dependencies = [...seen];
377	  if (node.id === entryId && dependencies.length > 0) {
378	    throw new Error(`entry node ${node.id} must not declare dependencies`);
379	  }
380	  return dependencies;
381	}
382	
383	// Successor edges and dependency ordering constraints together must stay
384	// acyclic across the whole definition — including branches a run would never
385	// take and nodes the entry cannot reach. The error names a node id chain
386	// whose first and last entries match and whose steps are real edges or
387	// dependency relations.
388	function detectCycles(nodes) {
389	  const adjacency = new Map([...nodes.keys()].map(id => [id, []]));
390	  for (const [id, node] of nodes) {
391	    adjacency.get(id).push(...successorTargets.get(node));
392	    for (const dependency of nodeDependencies.get(node)) {
393	      adjacency.get(dependency).push(id);
394	    }
395	  }
396	  const color = new Map([...nodes.keys()].map(id => [id, 'white']));
397	  const stack = [];
398	  const visit = id => {
399	    color.set(id, 'gray');
400	    stack.push(id);
401	    for (const target of adjacency.get(id)) {
402	      if (color.get(target) === 'gray') {
403	        const chain = [...stack.slice(stack.indexOf(target)), target];
404	        throw new Error(`cycle is present: ${chain.join(' -> ')}`);
405	      }
406	      if (color.get(target) === 'white') visit(target);
407	    }
408	    stack.pop();
409	    color.set(id, 'black');
410	  };
411	  for (const id of nodes.keys()) {
412	    if (color.get(id) === 'white') visit(id);
413	  }
414	}
415	
416	export function validateWorkflow(workflow) {
417	  assertPlainObject(workflow, 'workflow');
418	  if (typeof workflow.id !== 'string' || !workflow.id.trim()) throw new Error('workflow.id is required');
419	  if (typeof workflow.entry !== 'string' || !workflow.entry.trim()) throw new Error('workflow.entry is required');
420	  if (!Array.isArray(workflow.nodes) || workflow.nodes.length === 0) throw new Error('workflow.nodes must not be empty');
421	
422	  const nodes = new Map();
423	  for (const node of workflow.nodes) {
424	    assertPlainObject(node, 'node');
425	    if (typeof node.id !== 'string' || !node.id.trim()) throw new Error('every node requires an id');
426	    if (nodes.has(node.id)) throw new Error(`duplicate node id: ${node.id}`);
427	    if (!NODE_TYPES.has(node.type)) throw new Error(`unsupported node type: ${node.type}`);
428	    nodes.set(node.id, node);
429	  }
430	  if (!nodes.has(workflow.entry)) throw new Error(`entry node does not exist: ${workflow.entry}`);
431	
432	  let requiresSingleEnd = false;
433	  for (const node of nodes.values()) {
434	    successorTargets.set(node, normalizeSuccessors(node, nodes));
435	    const dependencies = normalizeDependencies(node, nodes, workflow.entry);
436	    nodeDependencies.set(node, dependencies);
437	    const usesArraySuccessors = node.type !== 'end' && node.type !== 'condition' && Array.isArray(node.next);
438	    if (usesArraySuccessors || dependencies.length > 0) requiresSingleEnd = true;
439	    if (node.type === 'form') {
440	      formSchemas.set(node, compileFormSchema(node));
441	    }
442	    if (node.type === 'condition') {
443	      compiledConditions.set(node, compileCondition(node.condition, node.id));
444	    }
445	    if (node.type === 'action') {
446	      actionBindings.set(node, compileAction(node));
447	    }
448	  }
449	
450	  if (requiresSingleEnd) {
451	    const endCount = [...nodes.values()].filter(node => node.type === 'end').length;
452	    if (endCount !== 1) {
453	      throw new Error('workflows using array successors or dependsOn must declare exactly one end node');
454	    }
455	  }
456	
457	  detectCycles(nodes);
458	  return nodes;
459	}
460	
461	function lookupOwn(root, segments) {
462	  let current = root;
463	  for (const part of segments) {
464	    if (!isUsableObject(current) || !Object.hasOwn(current, part)) {
465	      return { exists: false };
466	    }
467	    current = current[part];
468	  }
469	  return { exists: true, value: current };
470	}
471	
472	// Evaluates a compiled condition against the cloned execution input. Compounds
473	// short-circuit in declaration order, so a bad value inside a skipped child is
474	// never observed. A non-skipped numeric comparison whose inputs cannot convert
475	// to finite numbers is reported as an invalid_condition error instead.
476	function runCondition(compiled, input, nodeId, position = '$') {
477	  if (compiled.kind === 'not') {
478	    const child = runCondition(compiled.child, input, nodeId, `${position}.not`);
479	    if (!child.ok) return child;
480	    return { ok: true, value: !child.value };
481	  }
482	  if (compiled.kind === 'all' || compiled.kind === 'any') {
483	    for (let i = 0; i < compiled.children.length; i += 1) {
484	      const child = runCondition(compiled.children[i], input, nodeId, `${position}.${compiled.kind}[${i}]`);
485	      if (!child.ok) return child;
486	      if (compiled.kind === 'all' && !child.value) return { ok: true, value: false };
487	      if (compiled.kind === 'any' && child.value) return { ok: true, value: true };
488	    }
489	    return { ok: true, value: compiled.kind === 'all' };
490	  }
491	
492	  const where = `condition node ${nodeId} at ${position}`;
493	  const left = lookupOwn(input, compiled.segments);
494	  if (!left.exists) return { ok: true, value: false };
495	
496	  if (compiled.operator === 'exists') return { ok: true, value: true };
497	
498	  let right;
499	  if (compiled.valueSegments) {
500	    const lookedUp = lookupOwn(input, compiled.valueSegments);
501	    if (!lookedUp.exists) return { ok: true, value: false };
502	    right = lookedUp.value;
503	  } else {
504	    right = compiled.value;
505	  }
506	
507	  if (compiled.operator === 'eq') {
508	    return { ok: true, value: left.value === right };
509	  }
510	
511	  const leftNumber = toComparableNumber(left.value);
512	  if (leftNumber === null) {
513	    return { ok: false, error: `${where}: value at field cannot convert to a finite number` };
514	  }
515	  let rightNumber;
516	  if (compiled.valueSegments) {
517	    rightNumber = toComparableNumber(right);
518	    if (rightNumber === null) {
519	      return { ok: false, error: `${where}: value at valueField cannot convert to a finite number` };
520	    }
521	  } else {
522	    rightNumber = compiled.numericValue;
523	  }
