679	// Returns an early-termination result (invalid_input / invalid_condition)
680	// or null when execution should continue.
681	function applyRegularNode(node, state) {
682	  if (node.type === 'action') {
683	    state.context.output[node.id] = node.message ?? `action:${node.id}`;
684	  }
685	  if (node.type === 'form') {
