709	// definition has a function registered — including actions on untaken
710	// branches and entry-unreachable nodes.
711	function verifyOperations(nodes, operations) {
712	  for (const node of nodes.values()) {
713	    const binding = actionBindings.get(node);
714	    if (binding && binding.name !== null) {
715	      if (!isUsableObject(operations)
716	        || !Object.hasOwn(operations, binding.name)
717	        || typeof operations[binding.name] !== 'function') {
