test('rejects compensation declared on a non-business-action node', () => {
  const cases = [
    { id: 'start', type: 'trigger', next: 'done', compensation: { operation: 'x' } },
    { id: 'f', type: 'form', next: 'done', compensation: { operation: 'x' } },
    { id: 'c', type: 'condition', condition: { field: 'x', operator: 'exists' }, then: 'done', else: 'done', compensation: { operation: 'x' } },
    { id: 'done', type: 'end', result: 'ok', compensation: { operation: 'x' } },
  ];
  for (const node of cases) {
    const workflow = { id: 'wrong-node', entry: 'start', nodes: [node, { id: 'done', type: 'end', result: 'ok' }] };
    if (node.id === 'done' && node.type === 'end') workflow.nodes = [node];
    assert.throws(
      () => validateWorkflow(workflow),
      new RegExp(`node ${node.id}: compensation is only allowed on a business action node`),
    );
  }

  // A legacy message action is an action node but not a business action.
  const messageAction = compensableWorkflow();
  messageAction.nodes[2] = { id: 'a', type: 'action', message: 'm', compensation: { operation: 'undoA' }, next: 'b' };
  assert.throws(() => validateWorkflow(messageAction), /action node a: compensation is only allowed on an action that names an operation/);
