      { id: 'c', type: 'action', operation: 'opC', next: 'done' },
      { id: 'done', type: 'end', result: 'ok' },
    ],
  };
  const businessCalls = { opA: 0, opB: 0 };
  const undoCalls = { undoA: 0, undoB: 0 };
  const execution = await executeWorkflowAsync(workflow, {}, {
