  assert.deepEqual(undoCalls, { undoA: 2, undoB: 1 });
  assert.deepEqual(businessCalls, { opA: 1, opB: 1 });
  assert.deepEqual(execution.compensationAttempts.map(r => [r.nodeId, r.attempt, r.ok]), [
